        const char *name;
        VipsArgumentInstance *argument_instance;
        VipsArgumentClass *argument_class;
        GParamSpec *pspec;

        VIPS_DEBUG_MSG( "vips_call_options_set: %s = %s\n",
                option_name, value );

        /* Remove any leading "--" from the option name.
